package app.dayflow;
import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.widget.*;import androidx.core.content.FileProvider;import org.json.*;import java.io.*;import java.time.*;
/** Single-document grants only; the host validates identity and revisions before committing. */
final class DocumentPlugins {
 static final String MD="app.dayflow.markdown",ALMANAC="app.dayflow.almanac";static final int REQUEST=115;
 static boolean installed(MainActivity a,String pkg){try{a.getPackageManager().getPackageInfo(pkg,0);return true;}catch(Exception e){return false;}}
 static boolean ready(MainActivity a,String pkg){if(!installed(a,pkg)){ExtensionHub.show(a);a.message("请先安装对应可选插件");return false;}if(!a.prefs.getBoolean("plugin_enabled_"+pkg,true)){a.message("此插件已停用");return false;}if(a.getPackageManager().checkSignatures(a.getPackageName(),pkg)!=PackageManager.SIGNATURE_MATCH){a.message("插件签名与日栖不一致，请从官方发布页安装");return false;}return true;}
 static void edit(MainActivity a,JSONObject note){if(!ready(a,MD))return;if(a.prefs.contains("plugin_document")){LinearLayout page=a.fullPage("尚有插件暂存文档",a::home);page.addView(Ui.help(a,"先恢复或丢弃上次暂存，再打开另一篇笔记。原笔记不会因此删除。"));page.addView(Ui.button(a,"恢复上次暂存",true,()->recover(a)));page.addView(Ui.button(a,"丢弃暂存并打开本次笔记",false,()->{revoke(a);new File(a.getFilesDir(),"plugin-documents/active.md").delete();a.prefs.edit().remove("plugin_document").remove("plugin_document_nonce").commit();edit(a,note);}));return;}a.job(()->{JSONObject current=Data.get(a).find(note.getString("id"));if(current==null)current=note;File dir=new File(a.getFilesDir(),"plugin-documents");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("无法创建文档暂存目录");File file=new File(dir,"active.md");try(Writer out=new OutputStreamWriter(new FileOutputStream(file),java.nio.charset.StandardCharsets.UTF_8)){out.write(current.optString("content"));}JSONObject metadata=new JSONObject(current.toString());metadata.remove("content");metadata.remove("image_base64");metadata.remove("tf_raw");if(a.noteState!=null&&a.noteState.externalUri()!=null&&a.noteState.externalWritable())metadata.put("_external_uri",a.noteState.externalUri().toString());a.prefs.edit().putString("plugin_document",metadata.toString()).putString("plugin_document_nonce",java.util.UUID.randomUUID().toString()).commit();return "只将本次笔记交给本机Markdown插件";},()->{try{JSONObject metadata=new JSONObject(a.prefs.getString("plugin_document","{}"));Uri uri=FileProvider.getUriForFile(a,"app.dayflow.files",new File(a.getFilesDir(),"plugin-documents/active.md"));Intent request=new Intent("app.dayflow.action.MARKDOWN").setComponent(new ComponentName(MD,MD+".MainActivity")).setData(uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION).putExtra("dayflow_protocol",1).putExtra("dayflow_id",metadata.optString("id")).putExtra("dayflow_revision",metadata.optString("revision")).putExtra("dayflow_title",metadata.optString("title")).putExtra("dayflow_seed",Ui.primary(a)).putExtra("dayflow_document_token",a.prefs.getString("plugin_document_nonce",""));request.setClipData(ClipData.newRawUri("本次笔记",uri));a.startActivityForResult(request,REQUEST);}catch(Exception e){a.message(e.getMessage());}});}
 static synchronized JSONObject commit(Context c,String title,String checksum,String nonce)throws Exception{android.content.SharedPreferences prefs=c.getSharedPreferences("settings",0);String expected=prefs.getString("plugin_document_nonce","");if(expected.isEmpty()||!expected.equals(nonce))throw new SecurityException("文档授权已失效");JSONObject session=new JSONObject(prefs.getString("plugin_document","{}"));java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");String text;try(InputStream input=new java.security.DigestInputStream(new FileInputStream(new File(c.getFilesDir(),"plugin-documents/active.md")),digest)){text=MarkdownFiles.read(input);}String actual=android.util.Base64.encodeToString(digest.digest(),android.util.Base64.NO_WRAP);if(checksum==null||!actual.equals(checksum))throw new IOException("文档尚未完整写入，原笔记保留");Data db=Data.get(c);JSONObject current=db.find(session.getString("id"));boolean collision=current==null||current.optBoolean("deleted")||!current.optString("revision").equals(session.optString("revision"));JSONObject edited=current==null?new JSONObject(session.toString()):new JSONObject(current.toString());if(collision){String source=session.getString("id");edited.put("id",java.util.UUID.nameUUIDFromBytes(("dayflow:document-conflict:"+nonce).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString()).put("revision",java.util.UUID.randomUUID().toString()).put("ancestors",new JSONArray()).put("conflict_of",source).put("deleted",false);edited.remove("tf_id");edited.remove("tf_raw");edited.remove("tf_table");}edited.remove("_external_uri");edited.put("content",text).put("content_format","markdown");if(title!=null&&!title.trim().isEmpty())edited.put("title",collision?"[冲突副本] "+title:title);Data.validate(edited);if(collision||current==null||!text.equals(current.optString("content"))||!edited.optString("title").equals(current.optString("title")))db.save(edited);session.put("id",edited.getString("id")).put("revision",edited.getString("revision")).put("title",edited.optString("title"));String warning="";if(session.has("_external_uri")&&!collision)try(Writer out=new OutputStreamWriter(c.getContentResolver().openOutputStream(Uri.parse(session.getString("_external_uri")),"wt"),java.nio.charset.StandardCharsets.UTF_8)){out.write(MarkdownFiles.markdown(edited));MarkdownDocuments.wrote(c,Uri.parse(session.getString("_external_uri")),edited);}catch(Exception e){warning="本机笔记已保存，原文件无法写回，可从主应用导出";}prefs.edit().putString("plugin_document",session.toString()).commit();AgendaWidget.refresh(c);return new JSONObject().put("warning",warning).put("id",edited.getString("id")).put("revision",edited.getString("revision")).put("title",edited.optString("title")).put("conflict",collision);}
 static void result(MainActivity a,int result,Intent data){if(result!=android.app.Activity.RESULT_OK||data==null){revoke(a);a.message("插件未提交；暂存文档可从扩展中心恢复");return;}a.job(()->{JSONObject saved=commit(a,data.getStringExtra("dayflow_title"),data.getStringExtra("dayflow_sha256"),a.prefs.getString("plugin_document_nonce",""));revoke(a);new File(a.getFilesDir(),"plugin-documents/active.md").delete();a.prefs.edit().remove("plugin_document").remove("plugin_document_nonce").commit();return saved.optBoolean("conflict")?"笔记已更新，插件内容作为冲突副本保留":"Markdown笔记已保存并进入同步队列";},a::home);}
 static void recover(MainActivity a){if(a.prefs.contains("plugin_document")){LinearLayout page=a.fullPage("插件暂存文档",a::home);page.addView(Ui.help(a,"插件异常退出时原笔记不变；可将已写入的暂存文件恢复为副本。"));page.addView(Ui.button(a,"恢复暂存为独立笔记",true,()->a.job(()->{JSONObject session=new JSONObject(a.prefs.getString("plugin_document","{}"));String text;try(InputStream in=new FileInputStream(new File(a.getFilesDir(),"plugin-documents/active.md"))){text=MarkdownFiles.read(in);}JSONObject r=Data.make("note",session.optString("title")+" · 插件恢复").put("content",text).put("content_format","markdown");Data.validate(r);Data.get(a).save(r);revoke(a);new File(a.getFilesDir(),"plugin-documents/active.md").delete();a.prefs.edit().remove("plugin_document").remove("plugin_document_nonce").commit();return "已恢复，不覆盖原笔记";},a::home)));}}
 static void revoke(MainActivity a){try{Uri uri=FileProvider.getUriForFile(a,"app.dayflow.files",new File(a.getFilesDir(),"plugin-documents/active.md"));a.revokeUriPermission(MD,uri,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}}
 static void almanac(MainActivity a,LocalDate day){if(!ready(a,ALMANAC))return;try{a.startActivity(new Intent("app.dayflow.action.ALMANAC").setPackage(ALMANAC).putExtra("dayflow_protocol",1).putExtra("dayflow_date",day.toString()).putExtra("dayflow_seed",Ui.primary(a)));}catch(Exception e){a.message("无法打开黄历插件");}}
}
